import os, csv, json, numpy as np
try:
    from scipy.optimize import linear_sum_assignment
except Exception:
    linear_sum_assignment = None

N = 26
TOL = 1e-8

# Directories (with robust fallbacks)
D_NOE = 'storage/noesis/exports/sota_243'
D_SCI_CAND = [
    'storage/Scientia/nmap/n26',
    '/home/ubuntu/station_2/station_data/rooms/research/storage/lineages/scientia/nmap/n26',
]
D_PRO_CAND = [
    'storage/Prometheus/nmap/n26',
    'storage/prometheus/nmap/n26',
    '/home/ubuntu/station_2/station_data/rooms/research/storage/lineages/prometheus/nmap/n26',
]

OUT_DIR = 'storage/noesis/nmap'

CANON = {
  'xl':'xL','left':'xL','l':'xL','x_left':'xL',
  'xr':'xR','right':'xR','r':'xR','x_right':'xR',
  'yb':'yB','bottom':'yB','b':'yB','y_bottom':'yB',
  'yt':'yT','top':'yT','t':'yT','y_top':'yT',
  'xl.':'xL','xr.':'xR','yb.':'yB','yt.':'yT',
  'xL':'xL','xR':'xR','yB':'yB','yT':'yT'
}

def first_existing(paths):
    for p in paths:
        if isinstance(p, (list, tuple)):
            p = os.path.join(*p)
        if os.path.exists(p):
            return p
    return None

def read_pairs_raw(path):
    rows=[]
    with open(path,'r') as f:
        for ln in f:
            toks=[t for t in ln.replace(',', ' ').split() if t]
            if len(toks)<2: continue
            try:
                i=int(float(toks[0])); j=int(float(toks[1]))
            except:
                continue
            rows.append((i,j))
    return rows

def read_bound_raw(path):
    rows=[]
    with open(path,'r') as f:
        for ln in f:
            toks=[t for t in ln.replace(',', ' ').split() if t]
            if len(toks)<2: continue
            try:
                i=int(float(toks[0]))
            except:
                continue
            side_raw = toks[1].strip()
            side = CANON.get(side_raw.lower(), side_raw)
            side2 = CANON.get(side.lower().strip(' :;,'), side)
            if side2 in ('xL','xR','yB','yT'):
                rows.append((i, side2))
    return rows

def normalize_indices(rows, kind):
    # Decide 0-based vs 1-based and normalize to 0-based in [0..N-1]
    if kind=='pairs':
        idxs = [i for (i,_) in rows] + [j for (_,j) in rows]
    else:
        idxs = [i for (i,_) in rows]
    if not idxs:
        return set(), {'applied': False, 'mode': 'empty'}

    c0 = sum(0 <= v <= N-1 for v in idxs)
    c1 = sum(1 <= v <= N     for v in idxs)
    meta = {'applied': False, 'mode': 'as-is'}
    out=set()
    if c1 > c0 and all(1 <= v <= N for v in idxs):
        meta = {'applied': True, 'mode': 'minus_one'}
        if kind=='pairs':
            for (i,j) in rows:
                a,b = i-1, j-1
                if 0 <= a < N and 0 <= b < N and a!=b:
                    u,v = (a,b) if a<b else (b,a)
                    out.add((u,v))
        else:
            for (i,s) in rows:
                a = i-1
                if 0 <= a < N:
                    out.add((a,s))
    else:
        if kind=='pairs':
            for (i,j) in rows:
                if 0 <= i < N and 0 <= j < N and i!=j:
                    u,v = (i,j) if i<j else (j,i)
                    out.add((u,v))
        else:
            for (i,s) in rows:
                if 0 <= i < N:
                    out.add((i,s))
    return out, meta

def read_centers(path):
    rows=[]
    with open(path,'r') as f:
        for ln in f:
            toks=[t for t in ln.split() if t]
            if len(toks)>=2:
                rows.append([float(toks[0]), float(toks[1])])
    C=np.array(rows, float)
    if C.shape!=(N,2): raise ValueError(f"centers shape mismatch: {path} got {C.shape}")
    return C

def jaccard(A,B):
    I=A & B; U=A | B
    J=float(len(I))/float(len(U)) if len(U)>0 else 1.0
    return J, len(I), len(U), len(U)-len(I)

def align_map(CA, CB):
    M=np.sum((CA[:,None,:]-CB[None,:,:])**2, axis=2)
    if linear_sum_assignment is None:
        a_idx=np.lexsort((CA[:,1], CA[:,0]))
        b_idx=np.lexsort((CB[:,1], CB[:,0]))
        P=np.zeros(N, dtype=int); P[a_idx]=b_idx
        return P
    r,c=linear_sum_assignment(M)
    P=np.zeros(N, dtype=int); P[r]=c
    return P

def map_pairs(P, S):
    T=set()
    for (i,j) in S:
        if 0<=i<N and 0<=j<N:
            a=int(P[i]); b=int(P[j])
            if a==b: continue
            u,v=(a,b) if a<b else (b,a)
            T.add((u,v))
    return T

def map_bound(P, S):
    T=set()
    for (i,side) in S:
        if 0<=i<N:
            T.add((int(P[i]), side))
    return T

def load_pack(dir_pairs, dir_bound, centers_path=None):
    pr_raw = read_pairs_raw(os.path.join(dir_pairs, 'active_pairs_tol1e8.csv'))
    bd_raw = read_bound_raw(os.path.join(dir_bound, 'active_boundary_tol1e8.csv'))
    pairs, m_pairs = normalize_indices(pr_raw, 'pairs')
    bound, m_bound = normalize_indices(bd_raw, 'bound')
    C = read_centers(centers_path) if centers_path else None
    return {'pairs': pairs, 'bound': bound, 'centers': C,
            'meta': {'pairs_norm': m_pairs, 'bound_norm': m_bound}}

def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        json.dump(obj, f, indent=2, sort_keys=True)

def write_csv(path, header, rows):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', newline='') as f:
        w = csv.writer(f); w.writerow(header)
        for r in rows: w.writerow(r)

def pair_report(A, B, name_unaligned, name_aligned):
    # Unaligned
    Jb, Ib, Ub, Db = jaccard(A['bound'], B['bound'])
    Jp, Ip, Up, Dp = jaccard(A['pairs'], B['pairs'])
    write_json(f"{OUT_DIR}/{name_unaligned}.json",
               {"n":N,"boundary":{"jaccard":Jb,"intersection_size":Ib,"union_size":Ub},
                "pairs":{"jaccard":Jp,"intersection_size":Ip,"union_size":Up,"symdiff_size":Dp}})
    write_csv(f"{OUT_DIR}/{name_unaligned}.csv",
              ['n','boundary_j','boundary_intersection','boundary_union','pairs_j','pairs_intersection','pairs_union','pairs_symdiff'],
              [[N,Jb,Ib,Ub,Jp,Ip,Up,Dp]])

    # Aligned (A->B) if centers present
    if A['centers'] is not None and B['centers'] is not None:
        P = align_map(A['centers'], B['centers'])
        Ab = map_bound(P, A['bound']); Ap = map_pairs(P, A['pairs'])
        Jb2, Ib2, Ub2, Db2 = jaccard(Ab, B['bound'])
        Jp2, Ip2, Up2, Dp2 = jaccard(Ap, B['pairs'])
        write_json(f"{OUT_DIR}/{name_aligned}.json",
                   {"n":N,"alignment":"hungarian",
                    "boundary":{"jaccard":Jb2,"intersection_size":Ib2,"union_size":Ub2},
                    "pairs":{"jaccard":Jp2,"intersection_size":Ip2,"union_size":Up2,"symdiff_size":Dp2}})
        write_csv(f"{OUT_DIR}/{name_aligned}.csv",
                  ['n','alignment','boundary_j','boundary_intersection','boundary_union','pairs_j','pairs_intersection','pairs_union','pairs_symdiff'],
                  [[N,'hungarian',Jb2,Ib2,Ub2,Jp2,Ip2,Up2,Dp2]])

def construct_packing():
    # Resolve lineage dirs
    sci_dir = first_existing(D_SCI_CAND)
    pro_dir = first_existing(D_PRO_CAND)
    if not sci_dir or not pro_dir:
        raise FileNotFoundError("Missing lineage exports for Scientia or Prometheus.")

    # Load packs
    exp_noe = load_pack(D_NOE, D_NOE, centers_path='storage/noesis/latest_centers.txt')
    exp_sci = load_pack(sci_dir, sci_dir, centers_path=os.path.join(sci_dir,'centers.txt'))
    exp_pro = load_pack(pro_dir, pro_dir, centers_path=os.path.join(pro_dir,'centers.txt'))

    # Pairwise reports: Prometheus vs Noesis, Prometheus vs Scientia
    pair_report(exp_pro, exp_noe,
                "jaccard_prometheus_eval298_vs_noesis243_tol1e8",
                "jaccard_prometheus_eval298_vs_noesis243_aligned_tol1e8")
    pair_report(exp_pro, exp_sci,
                "jaccard_prometheus_eval298_vs_scientia259_tol1e8",
                "jaccard_prometheus_eval298_vs_scientia259_aligned_tol1e8")

    # 3-lineage consensus (unaligned sets)
    B_sets = [exp_noe['bound'], exp_sci['bound'], exp_pro['bound']]
    P_sets = [exp_noe['pairs'], exp_sci['pairs'], exp_pro['pairs']]
    B_inter = set.intersection(*B_sets) if B_sets else set()
    B_union = set.union(*B_sets) if B_sets else set()
    P_inter = set.intersection(*P_sets) if P_sets else set()
    P_union = set.union(*P_sets) if P_sets else set()
    cons = {
      "n": N,
      "lineages": ["Noesis_243","Scientia_259","Prometheus_298"],
      "boundary": {"intersection_size": len(B_inter), "union_size": len(B_union),
                   "sizes": [len(s) for s in B_sets]},
      "pairs": {"intersection_size": len(P_inter), "union_size": len(P_union),
                "sizes": [len(s) for s in P_sets]}
    }
    write_json(f"{OUT_DIR}/consensus_n26_noesis243_scientia259_prometheus298_tol1e8.json", cons)
    write_csv(f"{OUT_DIR}/consensus_n26_noesis243_scientia259_prometheus298_tol1e8.csv",
              ['n','boundary_intersection','boundary_union','pairs_intersection','pairs_union',
               'sizes_noesis','sizes_scientia','sizes_prometheus'],
              [[N, len(B_inter), len(B_union), len(P_inter), len(P_union),
                len(B_sets[0]), len(B_sets[1]), len(B_sets[2])]])

    # Return current Noesis packing unchanged
    c = np.loadtxt('storage/noesis/latest_centers.txt')
    r = np.loadtxt('storage/noesis/latest_radii.txt')
    return np.array(c, float).reshape(N,2), np.array(r, float).reshape(N,)
